            eh = eh * 0x9E3779B1u + static_cast<uint32_t>(exeOpcode + 1);
            eh = eh * 0x9E3779B1u + static_cast<uint32_t>((exeClass << 3) | exeRemain);
            eh = eh * 0x9E3779B1u + static_cast<uint32_t>(buf.size() & 15);
